initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Temporal Entity ${entity} 
        with an id set to ${temporal_entity_representation_id} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Temporal Representation Of Entity With Returning Response with Response Status Code set to 204     and
        Retrieve Temporal Representation Of Entity with Response Status Code set to ${response1.status_code}
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/temporal/entities/{temporal_entity_representation_id}'
        method set to 'DELETE'
        Delete Temporal Representation Of Entity With Returning Response with id set to '${temporal_entity_representation_id}'
}
